function numDecodings(s) {
  const memo = new Map();
  const count = (i) => {                         // decodings of s[i..]
    if (i === s.length) return 1;                // nothing left: one way
    if (s[i] === "0") return 0;                  // no letter starts with 0
    if (memo.has(i)) return memo.get(i);
    let total = count(i + 1);                    // one digit
    if (i + 1 < s.length && Number(s.slice(i, i + 2)) <= 26) total += count(i + 2);   // two digits
    memo.set(i, total);
    return total;
  };
  return count(0);
}

from functools import cache

def num_decodings(s):
    @cache
    def count(i):                         # decodings of s[i:]
        if i == len(s):
            return 1                      # nothing left: one way
        if s[i] == "0":
            return 0                      # no letter starts with 0
        total = count(i + 1)              # one digit
        if i + 1 < len(s) and int(s[i:i + 2]) <= 26:
            total += count(i + 2)         # two digits
        return total
    return count(0)

