int count(String s, int i) {                     // decodings of s[i..]
    if (i == s.length()) return 1;               // nothing left: one way
    if (s.charAt(i) == '0') return 0;            // no letter starts with 0
    if (memo[i] != null) return memo[i];
    int total = count(s, i + 1);                 // one digit
    if (i + 1 < s.length() && Integer.parseInt(s.substring(i, i + 2)) <= 26) total += count(s, i + 2);   // two digits
    return memo[i] = total;
}

int count(const string& s, vector<int>& memo, int i) {   // decodings of s[i..]
    if (i == (int)s.size()) return 1;            // nothing left: one way
    if (s[i] == '0') return 0;                   // no letter starts with 0
    if (memo[i] != -1) return memo[i];
    int total = count(s, memo, i + 1);           // one digit
    if (i + 1 < (int)s.size() && stoi(s.substr(i, 2)) <= 26) total += count(s, memo, i + 2);   // two digits
    return memo[i] = total;
}

